    def test_sign(
        self,
        name: str,
        pk_bytes: bytes,
        msg: bytes,
        ctx: bytes,
        sig: bytes,
        expected: bool,
    ):
        dsa = ML_DSA(ParameterSet.ML_DSA_87)

        try:
            pk = VerificationKey.from_bytes(pk_bytes)
        except ValueError:
            self.assertFalse(expected)
        else:
            actual = dsa.verify(pk, msg, ctx, sig)
            self.assertIs(actual, expected)
